+static bool str_has_crlf(const char *p)
+{
+  while(p && *p) {
+    if(ISNEWLINE(*p))
+      return TRUE;
+    p++;
+  }
+  return FALSE;
+}
+
+static bool list_has_crlf(const struct curl_slist *slist)
+{
+  while(slist) {
+    if(str_has_crlf(slist->data))
+      return TRUE;
+    slist = slist->next;
+  }
+  return FALSE;
+}
